<?php
declare(strict_types=1); require_once __DIR__.'/includes/functions.php'; if(!installed()) redirect('/install.php');
$s=db()->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.is_active=1');$s->execute([$_GET['slug']??'']);$p=$s->fetch();if(!$p){http_response_code(404);exit('Produit introuvable');}
$event=db()->prepare('INSERT INTO events(type,product_id) VALUES(?,?)');$event->execute(['view',$p['id']]);
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($p['name'])?> · <?=e(setting('shop_name'))?></title><link rel="stylesheet" href="/public/css/app.css"></head><body><header class="top"><a class="brand" href="/">← <?=e(setting('shop_name'))?></a></header><main class="container detail"><div><?php if($p['image']):?><img class="detail-img" src="/<?=e(UPLOAD_URL.$p['image'])?>" alt="<?=e($p['name'])?>"><?php else:?><div class="detail-img placeholder">🛍️</div><?php endif;?></div><div><small><?=e($p['category_name']??'')?></small><h1><?=e($p['name'])?></h1><div class="price"><?=money($p['price'])?></div><p><?=nl2br(e($p['description']))?></p><label>Quantité<input id="qty" type="number" min="1" value="1"></label><a id="wa" class="btn whatsapp" target="_blank" rel="noopener" href="<?=e(whatsapp_link(setting('whatsapp_number'),$p['name'],(float)$p['price']))?>">Commander sur WhatsApp</a></div></main><script type="module" src="/public/js/app.js"></script><script>window.product={name:<?=json_encode($p['name'])?>,price:<?=json_encode((float)$p['price'])?>,number:<?=json_encode(setting('whatsapp_number'))?>};</script></body></html>